import { test, expect } from '@playwright/test';

test.describe('Checkbox State Management', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkboxes');
  });

  test('should toggle checkbox states correctly and update form state', async ({ page }) => {
    // Verify initial state: first checkbox unchecked, second checked
    const firstCheckbox = page.getByRole('checkbox', { name: /first option/i });
    await expect(firstCheckbox).toBeUnchecked();

    const secondCheckbox = page.getByRole('checkbox', { name: /second option/i });
    await expect(secondCheckbox).toBeChecked();

    // Verify form submission button is disabled when no checkboxes are checked
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeDisabled();

    // Toggle first checkbox to check both
    await firstCheckbox.click();
    await expect(firstCheckbox).toBeChecked();
    await expect(secondCheckbox).toBeChecked();

    // Verify form submission button is now enabled
    await expect(submitButton).not.toBeDisabled();

    // Verify form data is updated to reflect both checkboxes being checked
    const formData = await page.evaluate(() => {
      const inputs = document.querySelectorAll('input[type="checkbox"]');
      return Array.from(inputs).reduce((acc, input) => {
        acc[input.name] = input.checked;
        return acc;
      }, {});
    });
    expect(formData).toEqual({ firstOption: true, secondOption: true });

    // Verify form is still visible and accessible
    await expect(page).toBeVisible();
  });

  test('should handle unchecking second checkbox and leave only first checked', async ({ page }) => {
    // Verify initial state: first checkbox unchecked, second checked
    const firstCheckbox = page.getByRole('checkbox', { name: /first option/i });
    await expect(firstCheckbox).toBeUnchecked();

    const secondCheckbox = page.getByRole('checkbox', { name: /second option/i });
    await expect(secondCheckbox).toBeChecked();

    // Toggle second checkbox to uncheck
    await secondCheckbox.click();
    await expect(secondCheckbox).toBeUnchecked();

    // Verify only first checkbox remains checked
    await expect(firstCheckbox).toBeChecked();

    // Verify form submission button is still enabled
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).not.toBeDisabled();

    // Verify form data reflects only first checkbox being checked
    const formData = await page.evaluate(() => {
      const inputs = document.querySelectorAll('input[type="checkbox"]');
      return Array.from(inputs).reduce((acc, input) => {
        acc[input.name] = input.checked;
        return acc;
      }, {});
    });
    expect(formData).toEqual({ firstOption: true, secondOption: false });

    // Verify form is still visible and accessible
    await expect(page).toBeVisible();
  });
});
